// Posty — Workflow 1 decision node. parse.js and build-index.js pasted verbatim.
// Tested by ./scripts/test-nodes and ./scripts/test-parser.

// Posty — QU parsing and status classification.
//
// This file is the single source of truth for how a Slack message becomes an index row.
// It is pasted verbatim into the Code nodes of Workflow 1 (index refresh) and Workflow 3
// (digest). Keep it dependency-free and side-effect-free so `./scripts/test-parser` can
// run it offline, and so the same code that is tested is the code that ships.
//
// Rules come from the build handoff §9. Do not tighten them without re-reading it:
// every shape below was taken from a real post in #newpostprojects or #releaseme.



// Handoff §9: case-insensitive, first match wins. {4,6} is deliberate headroom — real
// numbers are 5 digits but QU-50052 exists and the range is not contiguous. Do not
// narrow to {5}. The separator is not reliably a slash: space, dash, double space and
// underscore all occur, hence the character class. `QU_13577` is real and appears in both
// channels — before the underscore was added, that project was invisible to Posty
// entirely, on the intake side and the release side.
// Separators seen in real posts: dash, underscore, space, double space, none at all, and
// " - " with spaces on both sides. `QU - 17295 ref 17037` is real and appears in BOTH
// channels — before the surrounding whitespace was allowed, that project was invisible on
// the intake side and the release side alike.
//
// Widening this was diffed across all 1,658 backfilled messages: 2 newly matched, 0
// extractions changed. Re-run that diff before widening it further.
const QU_RE = /QU[\s]*[-_]?[\s]*(\d{4,6})/i;

// A synthetic key for a keyless project. Derived from the post's own ts, so it is unique,
// stable for the life of the row, and obviously not a real QU number at a glance.
//
// It deliberately cannot join an intake post to a separate release post — those are two
// different messages with no shared identifier, and guessing a link between them would be
// exactly the heuristic §9 warns against. It does not need to: releases now happen by
// reacting to the intake post, which resolves through the row's own source_ts.
// Handoff §9: (CANCELLED) anywhere in a #releaseme post means CANCELLED, not RELEASED.
// A naive diff scores it as released, which is wrong. Currently affects QU-17590.
const CANCELLED_RE = /\(\s*CANCELLED\s*\)/i;

// A Studio M / van recording is a production service (a recording session or a studio /
// mobile-van rental), NOT a releasable deliverable. Set by Tara 2026-09-08: once one of
// these is announced in #newpostprojects it is logged and left alone — it never enters the
// open pool to be chased, and it is never marked RELEASED. Matched by the phrases that
// name the service; the bare word "van" is deliberately excluded (it appears in "Van
// Digital" and elsewhere and over-matches). The status these rows carry is STUDIO_M below.
const STUDIO_M_RE = /studio\s*m|van\s*record|os\s*van/i;

function isStudioM(text) {
  return typeof text === 'string' && STUDIO_M_RE.test(text);
}

// The status value for those rows. A distinct state, neither OPEN (build-digest and the
// reminders only look at OPEN, so these drop out of both) nor RELEASED (so they never read
// as shipped to Accounting). The release path must treat it like RELEASED/CANCELLED and
// never overwrite it.
const STUDIO_M_STATUS = 'STUDIO M';

// Only these people announce projects. Set by Tara 2026-08-31 to keep channel chatter out
// of the index — a message from anyone else is not a project post, whatever it contains.
//
// This is a policy list, not a heuristic: it is maintained by a human who knows who the
// post engineers are, which is the only thing that reliably distinguishes an announcement
// from a conversation.
//
// **Add new post engineers here on their first day.** Until someone is on this list their
// posts are invisible to Posty — which is the intended behaviour, and also the way this
// list silently goes wrong. `isPostEngineer` is checked in the Workflow 2 classifier and in
// build-index.js, and a skipped message that DID carry a QU is logged with its code so the
// omission is discoverable in the execution list rather than silent.
const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'elijah',
  'U08V3CKDGJF': 'howard',
};

function isPostEngineer(user) {
  return Object.prototype.hasOwnProperty.call(POST_ENGINEERS, String(user || '').trim());
}

// Names are for grouping the digest. A row whose author is not on the list — a historical
// row from before the allowlist, or a blank posted_by — groups under "unassigned" rather
// than being hidden, so nothing falls out of a total.
function engineerName(user) {
  const u = String(user || '').trim();
  return POST_ENGINEERS[u] || 'unassigned';
}

// The "New Project" intake form (Slack Workflow Builder) posts announcements as a bot, not
// as the human who filled it in — so the post has no `user`, carries a `bot_id`/`subtype:
// bot_message`, and would be dropped by both the noise filter and the post-engineer gate.
// These are the bot/app identities of the APPROVED intake workflows, maintained the same way
// as POST_ENGINEERS: a post from one of these, carrying a QU, is a project announcement.
//
// The message payload identifies the workflow by bot_id (always present) or app_id — NOT by
// the "Wf…" Workflow Builder id, which never appears on the post. **If the workflow is
// rebuilt from scratch its bot/app id changes and must be added here**, exactly like adding
// a new post engineer. Added 2026-09-10 when the form intake went live.
const INTAKE_WORKFLOW_BOTS = { 'B0C0US9CXU2': 'New Project form' };
const INTAKE_WORKFLOW_APPS = { 'A0C0YBR1GG4': 'New Project form' };

function isIntakeWorkflow(msg) {
  if (!msg || typeof msg !== 'object') return false;
  const bot = String(msg.bot_id || '').trim();
  const app = String(msg.app_id || '').trim();
  return Object.prototype.hasOwnProperty.call(INTAKE_WORKFLOW_BOTS, bot)
      || Object.prototype.hasOwnProperty.call(INTAKE_WORKFLOW_APPS, app);
}

// The form writes the person who submitted it as a leading Slack mention, e.g.
// "<@U026N6E1R> - *QU-*12345 / …". That mention is the real poster, and recording it as
// posted_by is what lets the react-to-release flow work for form posts too — the engineer
// who filed the project can react to release it, even though the message came from the bot.
function submitterFromText(text) {
  const m = String(text == null ? '' : text).match(/<@([A-Z0-9]+)>/);
  return m ? m[1] : '';
}

// The stored, human-readable form of a workflow post: drop the leading "<@submitter> -"
// (that is metadata, not the project) and the mrkdwn bold markers, leaving the clean project
// line "QU-12345 / Agency / …" that the index, the digest and the #releaseme repost all use.
function cleanWorkflowText(text) {
  return String(text == null ? '' : text)
    .replace(/^\s*<@[A-Z0-9]+>\s*[-–—:]?\s*/, '')
    .replace(/\*/g, '')
    .trim();
}

const NEWPOST_CHANNEL = 'C1SJE7404';
const RELEASEME_CHANNEL = 'CC9EG3K8C';

// Returns the QU digits as a string with no QU- prefix, or null when the message
// carries no code at all. String, not number: these are identifiers, and leading
// zeros would be lost the moment anything coerces them.
function extractQu(text) {
  if (typeof text !== 'string') return null;
  // Strip mrkdwn bold/italic asterisks first: the "New Project" intake form writes the code
  // as *QU-*12345, and the `*` between the separator and the digits would otherwise defeat
  // QU_RE. `*` is never part of a QU, so removing it is safe for ordinary posts too.
  const m = text.replace(/\*/g, '').match(QU_RE);
  return m ? m[1] : null;
}

// Slack's conversations.history escapes &, < and > in message text, so PC&V arrives as
// PC&amp;V. Stored raw, the Sheet fills with &amp; and is unpleasant to read, and so is
// any digest line built from it.
//
// Decode on the way IN, escape again on the way OUT (escapeForSlack, in resolve-release).
// The bytes Posty posts are therefore unchanged from the verified-working behaviour, while
// the stored copy is what a human would have typed.
//
// Order matters: &amp; must be decoded LAST, or "&amp;lt;" would turn into "<" instead of
// the literal "&lt;" it represents.
function decodeEntities(text) {
  if (typeof text !== 'string') return text;
  return text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}

// Every QU a #releaseme post closes.
//
// Usually one. But bulk release posts are common in the 2024 archive — several complete
// project lines in a single message — and "first match wins" (§9) then closes the first
// and leaves the rest open forever. That is 24 projects wrongly in the chase list.
//
// So on the RELEASE side, take every code. The one thing that must not be swept up is a
// BACK-REFERENCE: "(Addcost from QU-10317)" mentions an older project without releasing
// it, and closing it would tell Accounting to bill work that never shipped.
//
// Intake keeps first-match-wins: a post announcing several projects is a different
// question, and getting it wrong there invents projects rather than closing them.
const BACKREF_RE = /\b(?:from|ref|per|vs|supersedes|replaces|addcost\s+(?:from|of))\s*:?\s*$/i;

function extractReleasedQus(text) {
  if (typeof text !== 'string') return [];
  const s = text.replace(/\*/g, '');   // see extractQu: tolerate bold *QU-* on the release side too
  const re = new RegExp(QU_RE.source, 'gi');
  const found = [];
  let m;
  while ((m = re.exec(s)) !== null) {
    const before = s.slice(Math.max(0, m.index - 40), m.index);
    if (found.length && BACKREF_RE.test(before)) continue;
    if (found.indexOf(m[1]) === -1) found.push(m[1]);
  }
  return found;
}

// A QU- or QU_ prefix with no digits after it. This is the agreed posting convention:
// when a project has no code yet — pro bono, awaiting assignment, placeholder — the poster
// still writes "QU-" so the post is recognisably a project.
//
// A rule people are TOLD beats a rule inferred from punctuation. This replaced an earlier
// attempt that guessed from slash counts.
const QU_MARKER_RE = /QU[\s]*[-_]/i;

function hasQuMarker(text) {
  return typeof text === 'string' && QU_MARKER_RE.test(text);
}

// Synthetic key for a marked-but-uncoded project, derived from the post's own ts so it is
// unique and stable. Returns null for an implausible ts: a shared key would silently
// collapse every uncoded project onto one row.
function syntheticKey(ts) {
  const t = String(ts == null ? '' : ts).trim();
  if (!/^\d{6,}(\.\d+)?$/.test(t)) return null;
  return 'NOQU-' + t;
}

function isCancelled(text) {
  return typeof text === 'string' && CANCELLED_RE.test(text);
}

// Slack ts -> ISO date in Manila local time.
//
// The timezone is a judgment call the handoff does not make. Hit Productions is in
// Manila and age_days is counted in working days people recognise, so a post made at
// 07:00 Manila must date to that morning and not to the previous day in UTC. Asia/Manila
// is UTC+8 with no DST, so the fixed offset is exact rather than an approximation.
const MANILA_OFFSET_MS = 8 * 60 * 60 * 1000;

function tsToDate(ts) {
  if (ts === null || ts === undefined) return null;
  const seconds = Number(String(ts).split('.')[0]);
  if (!Number.isFinite(seconds)) return null;
  return new Date(seconds * 1000 + MANILA_OFFSET_MS).toISOString().slice(0, 10);
}

// Whole-day difference between two ISO dates. Both are already Manila-local calendar
// dates, so this is plain date arithmetic — no timezone maths, and no drift from the
// clock time of day the digest happens to run at.
function ageDays(postedDate, asOfDate) {
  if (!postedDate || !asOfDate) return null;
  const a = Date.parse(postedDate + 'T00:00:00Z');
  const b = Date.parse(asOfDate + 'T00:00:00Z');
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.round((b - a) / 86400000);
}

// Handoff §7 Workflow 3: >= 90 escalated, 45..89 flagged, < 45 omitted entirely.
// The boundaries are inclusive at 45 and at 90 — a project at exactly 45 days appears.
function bucketOf(age) {
  if (!Number.isFinite(age)) return null;
  if (age >= 90) return 'ESCALATED';
  if (age >= 45) return 'FLAGGED';
  return null;
}

// Turn one Slack message into an index row fragment. The caller supplies the channel so
// the CANCELLED rule stays scoped to #releaseme, where the handoff puts it.
function parseMessage(msg) {
  const text = decodeEntities((msg && msg.text) || '');
  const ts = msg && msg.ts;
  const channel = (msg && msg.channel) || '';
  let qu = extractQu(text);
  let synthetic = false;

  // Marked as a project but carrying no code -> track it under a synthetic key. It ages,
  // buckets and can be rocketed like anything else; when the real code arrives the poster
  // reposts with it.
  if (!qu && hasQuMarker(text)) {
    qu = syntheticKey(ts);
    synthetic = qu !== null;
  }

  // No QU digits and no QU- marker -> UNTRACKED. Never counted as open or as released.
  // Deliberately simple: a project is tracked when it carries a QU code, and not
  // otherwise. Codeless posts — placeholder codes, "QU-Not Available", foreign numbering,
  // "(NO Q-CODE)", pro bono — were briefly tracked under synthetic keys on 2026-08-31 and
  // that was reverted the same day in favour of a posting convention: post engineers write
  // a QU code, always.
  //
  // Nothing is lost by this. UNTRACKED rows still appear in the digest's "needs manual
  // check" section, so codeless work stays visible to a human — it simply is not counted,
  // aged or releasable, none of which can be done honestly without an identifier.
  if (!qu) {
    return {
      qu_number: null,
      synthetic: false,
      source_channel: channel,
      source_ts: String(ts),
      source_text: text,
      posted_date: tsToDate(ts),
      status: 'UNTRACKED',
    };
  }

  const cancelled = channel === RELEASEME_CHANNEL && isCancelled(text);

  return {
    qu_number: qu,
    synthetic,
    source_channel: channel,
    source_ts: String(ts),
    source_text: text,
    posted_date: tsToDate(ts),
    status: cancelled ? 'CANCELLED' : (channel === RELEASEME_CHANNEL ? 'RELEASED' : 'OPEN'),
  };
}

// Posty — Workflow 1's decision node, as a testable module.
//
// Pasted into the `Build Index` Code node. Pure: takes what the workflow read, returns what
// the workflow should write. No I/O, so `./scripts/test-nodes` can run it offline against
// real fixtures. Handoff §7 Workflow 1.
//
// The important design choice: this returns ONLY changed rows, never the whole index.
// A blind appendOrUpdate over every row would overwrite `posted_date` with the newer
// duplicate's date, which is precisely what §7 step 4 forbids — aging has to be measured
// from when a project was FIRST announced, not the last time someone re-posted it.





// Joins, leaves, pins and the rest are not project posts. They are skipped for PARSING
// but still counted for the watermark below — see the note on maxTs.
function isNoise(m) {
  return Boolean(m.subtype) && m.subtype !== 'thread_broadcast';
}

// Posty's own posts. Applied to the INTAKE channel only — in #releaseme Posty IS the
// author of every release, so filtering bots there would blind the release side entirely.
// Checked before fromStranger so Posty never lands in `skipped`, which exists to surface
// real projects that went untracked; a bot in that list is a false positive that trains
// people to ignore it.
function fromBot(m) {
  return Boolean(m.bot_id) || m.subtype === 'bot_message';
}

// Messages from anyone who is not a post engineer are not project announcements. Applied
// to the INTAKE channel only: #releaseme posts come from Posty itself and from whoever
// posted a release by hand before Posty existed, and filtering those would break the
// historical diff.
function fromStranger(m, parse) {
  return typeof parse.isPostEngineer === 'function' && !parse.isPostEngineer(m.user);
}

function buildIndex(input) {
  const {
    existingRows = [],      // current posty_qu_index contents
    newpostMessages = [],   // messages newer than last_newpost_ts
    releasemeMessages = [], // messages newer than last_releaseme_ts
    parse = P,
    nowIso,
  } = input;

  const byQu = new Map();
  for (const r of existingRows) {
    if (r && r.qu_number) byQu.set(String(r.qu_number), r);
  }

  const changed = new Map();   // qu_number -> row to write
  const untracked = [];
  const skipped = [];          // QU-bearing posts from people not on the list

  // --- intake -------------------------------------------------------------
  // Oldest first so that "keep the oldest posted_date" needs no comparison: the first
  // time we see a QU is the earliest announcement, and we simply never overwrite it.
  const intake = [...newpostMessages].sort((a, b) => Number(a.ts) - Number(b.ts));

  for (const m of intake) {
    // The "New Project" intake form posts as a bot with no `user`, so it would be dropped by
    // both isNoise (subtype bot_message) and fromBot. Recognise the approved workflow and let
    // it through, taking the SUBMITTER from the form's leading mention as the poster and the
    // cleaned line as the text. Everything after this point is the same as a human post.
    const wf = typeof parse.isIntakeWorkflow === 'function' && parse.isIntakeWorkflow(m);
    if (!wf) {
      if (isNoise(m)) continue;
      if (fromBot(m)) continue;
      if (fromStranger(m, parse)) {
        // Logged rather than dropped in silence: a QU here means a real project that will
        // not be tracked because its author is not on the list.
        const stray = parse.extractQu(m.text);
        if (stray) skipped.push({ qu_number: stray, user: m.user || '', ts: String(m.ts) });
        continue;
      }
    }
    const posted_by = wf ? parse.submitterFromText(m.text) : (m.user || '');
    const text = wf ? parse.cleanWorkflowText(m.text) : m.text;
    const row = parse.parseMessage({ text: text, ts: m.ts, channel: parse.NEWPOST_CHANNEL });

    if (!row.qu_number) {
      // §9 rule 2. UNTRACKED rows have no key, so they can only ever be appended.
      untracked.push({ ...row, released: 'FALSE', release_ts: '', release_date: '',
                       age_days: '', last_seen: nowIso, posted_by: posted_by });
      continue;
    }

    // Already indexed — a re-announcement. §7 step 4 / §9 rule 4: keep the older record
    // untouched. Touching last_seen alone would rewrite nothing meaningful and would cost
    // a write per re-post, so we skip entirely.
    if (byQu.has(row.qu_number) || changed.has(row.qu_number)) continue;

    changed.set(row.qu_number, {
      qu_number: row.qu_number,
      source_channel: row.source_channel,
      source_ts: row.source_ts,
      source_text: row.source_text,
      posted_date: row.posted_date,
      released: 'FALSE',
      release_ts: '',
      release_date: '',
      // A Studio M / van recording is a production service, not a releasable deliverable.
      // It is logged from the intake and then left alone: STUDIO M keeps it out of the open
      // pool (build-digest and the reminders only look at OPEN) and the release block below
      // never overwrites it. Tara, 2026-09-08.
      status: parse.isStudioM(row.source_text) ? parse.STUDIO_M_STATUS : 'OPEN',
      age_days: '',              // §6: derived at digest time, never stored stale
      last_seen: nowIso,
      // Slack is the source of truth for who posted. The live path already records this;
      // without it here, anything the nightly refresh catches has no poster and the
      // release poster-restriction cannot apply. Tara, 2026-09-08. For a form post this is
      // the submitter pulled from the leading mention, not the bot that posted it.
      posted_by: posted_by,
    });
  }

  // --- releases -----------------------------------------------------------
  const releases = [...releasemeMessages].sort((a, b) => Number(a.ts) - Number(b.ts));
  const seenThisRun = new Set();

  for (const m of releases) {
    if (isNoise(m)) continue;
    const rel = parse.parseMessage({ text: m.text, ts: m.ts, channel: parse.RELEASEME_CHANNEL });

    // A release post can close several projects at once — bulk posts list complete project
    // lines in one message. Take every code it names, minus back-references.
    const codes = typeof parse.extractReleasedQus === 'function'
      ? parse.extractReleasedQus(m.text) : (rel.qu_number ? [rel.qu_number] : []);

    for (const code of codes) {
    if (seenThisRun.has(code)) continue;             // §9 rule 3: first occurrence wins
    seenThisRun.add(code);

    const existing = changed.get(code) || byQu.get(code);

    // Released, but the intake post predates the index. Nothing to join to — do not invent
    // a row, because a row with no intake has no posted_date and would corrupt the aging.
    if (!existing) continue;

    // Already closed. Do not reopen, do not rewrite. This is what makes the nightly run
    // idempotent — re-reading the same release must be a no-op, not a churn of writes.
    // Do not reopen or rewrite a closed row; and never mark a Studio M recording released —
    // a release post that names its (often reused) QU must not flip it to shipped.
    if (existing.status === 'RELEASED' || existing.status === 'CANCELLED'
        || existing.status === parse.STUDIO_M_STATUS) continue;

    if (rel.status === 'CANCELLED') {
      // §9 rule 1. Cancelled is NOT released — a naive diff scores it as shipped, which
      // would tell Accounting to bill something that never went out.
      changed.set(code, { ...existing, status: 'CANCELLED', released: 'FALSE',
        release_ts: rel.source_ts, release_date: rel.posted_date, last_seen: nowIso });
    } else {
      changed.set(code, { ...existing, status: 'RELEASED', released: 'TRUE',
        release_ts: rel.source_ts, release_date: rel.posted_date, last_seen: nowIso });
    }
    }
  }

  // --- watermarks ---------------------------------------------------------
  // Highest ts of every message FETCHED, including the joins and leaves that isNoise()
  // skipped. The watermark means "read up to here", not "kept up to here". Computing it
  // from kept messages only would stall it behind a trailing join event and re-fetch that
  // tail on every run, forever. Falls back to the previous value when a channel had no new
  // messages — advancing past messages never read would skip them permanently.
  const maxTs = (msgs, fallback) => msgs.reduce(
    (hi, m) => (Number(m.ts) > Number(hi) ? String(m.ts) : hi), String(fallback || '0'));

  return {
    rows: [...changed.values(), ...untracked],
    state: {
      last_index_run: nowIso,
      last_newpost_ts: maxTs(newpostMessages, input.lastNewpostTs),
      last_releaseme_ts: maxTs(releasemeMessages, input.lastReleasemeTs),
    },
    skipped,
    summary: {
      skipped_strangers: skipped.length,
      new_projects: [...changed.values()].filter((r) => r.status === 'OPEN').length,
      released: [...changed.values()].filter((r) => r.status === 'RELEASED').length,
      cancelled: [...changed.values()].filter((r) => r.status === 'CANCELLED').length,
      untracked: untracked.length,
    },
  };
}

// --- wiring -----------------------------------------------------------------
const P = { NEWPOST_CHANNEL, RELEASEME_CHANNEL, parseMessage, extractQu,
            tsToDate, ageDays, bucketOf, isPostEngineer,
            extractReleasedQus, isStudioM, STUDIO_M_STATUS,
            isIntakeWorkflow, submitterFromText, cleanWorkflowText };

// Slack returns one item per page. Flatten to messages and keep EVERYTHING, subtypes
// included — buildIndex skips joins and leaves when parsing but still needs them to
// advance the watermark past a trailing join. bot_id and app_id are carried through so the
// "New Project" intake form (which posts as a bot) can be recognised. Filtering here stalls
// the watermark.
function flatten(items) {
  const out = [];
  for (const it of items) {
    for (const m of (it.json.messages || [])) {
      out.push({ ts: m.ts, text: m.text || '', subtype: m.subtype, user: m.user,
                 bot_id: m.bot_id, app_id: m.app_id });
    }
  }
  return out;
}

const state = $('Read State').first().json;
const existingRows = $('Read Index').all().map((i) => i.json);

const result = buildIndex({
  existingRows,
  newpostMessages: flatten($('Fetch Newpost').all()),
  releasemeMessages: flatten($('Fetch Releaseme').all()),
  parse: P,
  nowIso: new Date().toISOString(),
  lastNewpostTs: state.last_newpost_ts,
  lastReleasemeTs: state.last_releaseme_ts,
});

return [{ json: result }];

// Fan the changed rows out, one item per row, for appendOrUpdate.
// Returns zero items on a quiet night — Write Index is then skipped, which is correct.
const r = $input.first().json;
return (r.rows || []).map((row) => ({ json: row }));

// Always emits exactly one item, so the watermark advances even on a night with no new
// messages. row_number 2 targets the single data row of posty_state.
const r = $input.first().json;
return [{ json: { row_number: 2, ...r.state } }];

// Missed DM releases (Tara, 2026-09-28). A 🚀/✅ on a Posty DM list message is a release —
// but if Slack drops that live event the project silently stays open. So every hour, for each
// OPEN project Posty has DM'd its poster about (notify_ts), read that message's reactions. A
// release emoji from the poster that never took is reported to Tara, who is a release admin:
// her one reaction on the original post releases it the normal way (repost to #releaseme +
// sheet). This node picks what to check, grouped by poster so each DM is looked up once.
const rows = $('Read Index').all().map((i) => i.json);
